function prepRows() {
  const rows = [];
  Object.entries(PREP).forEach(([category, list]) => list.forEach(([q, a, k, d], i) => rows.push({ bank: 'prep', category, track: null, set_no: null, sort_order: i, difficulty: d, question: q, model_answer: a, keywords: k })));
  return rows;
}

function mockRows() {
  const rows = [];
  Object.entries(tracks).forEach(([track, t]) => {
    for (let s = 1; s <= 4; s++) {
      const diff = ['easy', 'medium', 'hard', 'hard'][s - 1];
      let order = 0;
      const push = (category, q, a, k, d) => rows.push({ bank: 'mock', category, track, set_no: s, sort_order: order++, difficulty: d || diff, question: q, model_answer: a, keywords: k });
      const intro = INTRO[s - 1]; push('intro', intro[1], intro[2], intro[3], 'easy');
      t.technical[s - 1].forEach((x) => push('technical', x[0], x[1], x[2], x[3] || diff));
      const c = t.coding[s - 1]; push('coding', c[0], c[1], c[2]);
      const p = t.project[s - 1]; push('project', p[0], p[1], p[2]);
      const h = HR_POOL[s - 1]; push('hr', h[1], h[2], h[3], 'medium');
    }
  });
  return rows;
}

